"""Карта ввода project.godot: каждое move_* имеет клавишу WASD, стрелку, кнопку крестовины и ось левого стика.

Реплеи ввод мимо Input не ловят (E-007: move_up/move_down были без оси 1 и стрелок).
"""
import re
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
KEY = {"move_left": (65, 4194319), "move_right": (68, 4194321),
       "move_up": (87, 4194320), "move_down": (83, 4194322)}
DPAD = {"move_left": 13, "move_right": 14, "move_up": 11, "move_down": 12}
AXIS = {"move_left": (0, -1.0), "move_right": (0, 1.0), "move_up": (1, -1.0), "move_down": (1, 1.0)}


def action_block(text, name):
    m = re.search(r"^%s=\{(.*?)^\}" % name, text, re.S | re.M)
    return m.group(1) if m else ""


def main():
    text = (ROOT / "project.godot").read_text(encoding="utf-8")
    errors = []
    for name in KEY:
        block = action_block(text, name)
        keys = {int(k) for k in re.findall(r'InputEventKey.*?"physical_keycode":(\d+)', block)}
        buttons = {int(b) for b in re.findall(r'InputEventJoypadButton.*?"button_index":(\d+)', block)}
        axes = {(int(a), float(v)) for a, v in re.findall(
            r'InputEventJoypadMotion.*?"axis":(\d+),"axis_value":(-?[\d.]+)', block)}
        for k in KEY[name]:
            if k not in keys:
                errors.append(f"{name}: нет клавиши physical_keycode={k}")
        if DPAD[name] not in buttons:
            errors.append(f"{name}: нет кнопки крестовины {DPAD[name]}")
        if AXIS[name] not in axes:
            errors.append(f"{name}: нет оси стика {AXIS[name]}")
    for e in errors:
        print("FAIL", e)
    if not errors:
        print("check_input_map: ok")
    return 1 if errors else 0


if __name__ == "__main__":
    sys.exit(main())
check_input_map: ok
